function woodTexture(){
  const c=document.createElement('canvas');
  c.width=c.height=64;
  const ctx=c.getContext('2d');
  ctx.fillStyle='#bb8d4e';
  ctx.fillRect(0,0,64,64);
  for(let i=0;i<190;i++){
    const yy=random()*64;
    ctx.strokeStyle=`rgba(${105+Math.floor(random()*55)},${65+Math.floor(random()*38)},28,${.04+random()*.14})`;
    ctx.lineWidth=.25+random()*.75;
    ctx.beginPath();
    ctx.moveTo(0,yy);
    ctx.bezierCurveTo(19,yy+(random()-.5)*2,45,yy+(random()-.5)*2,64,yy+.4);
    ctx.stroke();
  }
  const t=new THREE.CanvasTexture(c);
  t.wrapS=t.wrapT=THREE.RepeatWrapping;
  t.repeat.set(2.5,3);
  t.colorSpace=THREE.SRGBColorSpace;
  return t;
}
