function sampleTrack(values,time){
  if(time>=1400) return values[7];
  const i=Math.floor(time/200);
  const u=(time-i*200)/200;
  return cubic(
    values[Math.max(0,i-1)],
    values[i],
    values[Math.min(7,i+1)],
    values[Math.min(7,i+2)],
    u
  );
}
const pose={};
const leftTranslation=v(0,0,0);
const rightTranslation=v(0,0,0);
const writingTranslation=v(0,0,0);
const huggingTranslation=v(0,0,0);
const writingWristRelative=v(-1.76,.94,1.57).sub(writingPivot);
const huggingWristRelative=v(-.075,1.225,.98).sub(huggingPivot);
const writingWristDelta=v(0,0,0);
const huggingWristDelta=v(0,0,0);
const shoulderContact=v(-.43,2.15,.16);
const shoulderDelta=v(0,0,0);

function render(t){
  const finiteTime=Number.isFinite(t)?t:0;
  const phase=((finiteTime%1500)+1500)%1500;
  for(const name in tracks) pose[name]=sampleTrack(tracks[name],phase);

  leftTranslation.set(pose.leftX,pose.leftY,0);
  leftHead.position.copy(leftHeadPivot).add(leftTranslation);
  leftHead.rotation.set(pose.leftPitch,pose.leftYaw,pose.leftRoll);
  poseHeadSurface(leftHeadSkin,leftHeadPivot,leftHead.quaternion,leftTranslation);

  const turn=clamp(pose.leftYaw/.82,0,1);
  leftMouth.position.y=leftMouthBaseY-.035*turn;
  poseMouth(leftMouth,pose.leftOpen);

  rightTranslation.set(pose.rightX,pose.rightY,0);
  rightHead.position.copy(rightHeadPivot).add(rightTranslation);
  rightHead.rotation.set(pose.rightPitch,pose.rightYaw,0);
  poseHeadSurface(rightHeadSkin,rightHeadPivot,rightHead.quaternion,rightTranslation);
  poseMouth(rightMouth,pose.rightOpen);

  writingTranslation.set(pose.writeX,pose.writeY,pose.writeZ);
  writingHand.position.copy(writingPivot).add(writingTranslation);
  writingHand.rotation.set(pose.writePitch,pose.writeYaw,pose.writeRoll);
  writingWristDelta.copy(writingWristRelative)
    .applyQuaternion(writingHand.quaternion)
    .sub(writingWristRelative)
    .add(writingTranslation);
  poseArmSurface(sleeve,writingSkin,writingWristDelta);

  huggingTranslation.set(pose.hugX,pose.hugY,pose.hugZ);
  huggingHand.position.copy(huggingPivot).add(huggingTranslation);
  huggingHand.rotation.set(0,0,pose.hugRoll);
  huggingWristDelta.copy(huggingWristRelative)
    .applyQuaternion(huggingHand.quaternion)
    .sub(huggingWristRelative)
    .add(huggingTranslation);
  poseArmSurface(huggingSleeve,huggingSkin,huggingWristDelta);

  shoulderDelta.copy(shoulderContact)
    .sub(leftHeadPivot)
    .applyQuaternion(leftHead.quaternion)
    .add(leftHeadPivot)
    .add(leftTranslation)
    .sub(shoulderContact)
    .multiplyScalar(.5);
  farHand.position.copy(shoulderDelta);
  poseArmSurface(farSleeve,farSkin,shoulderDelta);

  restingArm.position.set(-.015*turn,.06*turn,-.025*turn);
  renderer.render(scene,ref);
}
